create table if not exists public.anthos_jj2_scenarios (
 id uuid primary key default gen_random_uuid(),
 source_story_id uuid not null unique references public.deep_dive_stories(id),
 petal_slug text not null references public.anthos_petals(slug),
 mode text not null check (mode in ('shared','individual')),
 slot smallint not null check (slot between 1 and 5),
 title text not null,
 opening_scene text not null,
 learning_objective text not null,
 research_lenses text[] not null default '{}',
 status text not null default 'draft' check (status in ('draft','in_review','beta_ready','retired')),
 content_version integer not null default 1,
 updated_at timestamptz not null default now(),
 created_at timestamptz not null default now(),
 unique(petal_slug,mode,slot)
);
alter table public.anthos_jj2_scenarios enable row level security;
revoke all on public.anthos_jj2_scenarios from anon,authenticated;
grant select,insert,update on public.anthos_jj2_scenarios to service_role;
create index if not exists anthos_jj2_scenarios_petal_idx on public.anthos_jj2_scenarios(petal_slug,mode,slot);
alter table public.anthos_jj2_rooms add column if not exists scenario_id uuid references public.anthos_jj2_scenarios(id);
alter table public.anthos_jj2_rooms add column if not exists experience_mode text not null default 'shared' check(experience_mode in ('shared','individual'));

with scene_inputs(petal_slug,rank,opening_scene) as (values
('friendship-admiration',1,'The local newspaper prints Jill''s name beside a hard-won award. Jack has already opened a spreadsheet of ways she could do even better next year. Jill is waiting to see what he says first.'),
('friendship-admiration',2,'Jack starts telling Jill about a strange encounter at the grocery store. Her phone lights up with an urgent work message just as he reaches the good part. He quietly says, ''Never mind.'''),
('friendship-admiration',3,'On a long drive, the radio goes silent in a dead zone. Jack reaches for another podcast; Jill looks at the empty passenger seat where their dog usually rides and asks if they can just talk.'),
('friendship-admiration',4,'An old shoebox spills photographs across the living-room floor. One picture makes Jill stop smiling and look toward the window; Jack has never heard the story behind it.'),
('friendship-admiration',5,'Jack returns from his hobby club thrilled with a tiny, handmade trophy. Jill has no interest in the hobby but has been asked to attend the celebration; the car leaves in ten minutes.'),
('friendship-admiration',6,'During a disastrously long dinner with friends, Jack whispers the old joke that once sent Jill into fits of laughter. Tonight she barely looks up. The waiter arrives carrying a flaming dessert.'),
('friendship-admiration',7,'Jill''s new friend invites her on a standing Friday-night outing. Jack has quietly kept Fridays open for the two of them, but neither has discussed the change.'),
('friendship-admiration',8,'At breakfast, Jack realizes their last five conversations were about calendars, groceries and laundry. Jill has a story she''s been trying to tell since Tuesday.'),
('friendship-admiration',9,'An old yearbook turns up while they clean the attic. The person in Jack''s senior photo seems nothing like the man making coffee downstairs, and Jill wonders what she still hasn''t learned.'),
('friendship-admiration',10,'Jack wants a crowded game night; Jill has already put on pajamas and picked a movie. Their friends are texting from the driveway, and neither wants to disappoint the other.'),
('communication-understanding',1,'Jill asks a serious question just as Jack is leaving for a difficult meeting. He promises, ''We''ll talk later,'' but the kitchen calendar is already full until Sunday.'),
('communication-understanding',2,'A passing comment about the dishwasher makes Jack defensive. Jill insists she was asking a real question, not criticizing him. The dishwasher door remains open between them.'),
('communication-understanding',3,'At 12:07 a.m., Jack remembers the conversation he''s been avoiding. Jill has a presentation at 7:30, but he has finally found the courage to bring it up.'),
('communication-understanding',4,'Jack makes a joke at the neighborhood cookout. Everyone laughs except Jill; on the drive home, the silence is louder than the radio.'),
('communication-understanding',5,'Jill has handled a dozen small tasks to keep the weekend running. Jack thanks the delivery driver with great enthusiasm but hasn''t noticed what she has done.'),
('communication-understanding',6,'During a difficult week, Jack gets unusually quiet. Jill types three different questions, deletes all of them, and finally finds him sitting alone on the porch.'),
('communication-understanding',7,'Jack tells a story about a frustrating phone call. Jill immediately offers a solution, but he says, ''That''s not what I meant.'' The same conversation is happening for the third time.'),
('communication-understanding',8,'At a family dinner, Jill gently challenges Jack''s version of a funny story. His brother keeps laughing, but Jack suddenly looks embarrassed in front of the entire table.'),
('communication-understanding',9,'Jack sends a difficult message and watches three typing dots appear, vanish and reappear. By the time Jill actually replies, he has imagined several different arguments.'),
('communication-understanding',10,'Jill arrives home expecting the plan to be obvious. Jack has arranged something entirely different, and both say, ''I thought you knew,'' at the same time.'),
('conflict-repair',1,'A late arrival and a lost reservation have turned the vacation into a parking-lot standoff. Jack blames the GPS; Jill points toward the beach they haven''t seen yet.'),
('conflict-repair',2,'Jack and Jill have each promised Christmas Day to a different family. Both mothers have purchased personalized pajamas, and the family group chat just added a seating chart.'),
('conflict-repair',3,'Two versions of the same argument are now circulating around the kitchen table. Jack remembers the words, Jill remembers the tone, and neither wants to concede.'),
('conflict-repair',4,'Jack offers an apology that begins with ''I''m sorry'' and ends with ''but you started it.'' Jill freezes with one hand on the front door.'),
('conflict-repair',5,'After a sharp exchange, the bedroom door slams. Ten minutes later, the kettle whistles and Jack realizes that avoiding the next conversation will be harder than making tea.'),
('conflict-repair',6,'A magnetic scoreboard for household chores becomes an actual scoreboard of grievances. Jill marks something in red; Jack asks whether last Tuesday''s laundry counts double.'),
('conflict-repair',7,'Every week, a harmless question about dinner turns into the same old fight. Tonight the argument somehow begins over a missing bottle of ketchup.'),
('conflict-repair',8,'Jack and Jill agreed to finish a conversation Sunday evening. It is Wednesday; the subject hasn''t returned, but the unopened notebook is still on the counter.'),
('conflict-repair',9,'A cruel remark hangs in the air after an argument. Jack and Jill both know an ordinary ''never mind'' will not make the sentence disappear.'),
('conflict-repair',10,'After three quiet days, the house is spotless and strangely uncomfortable. The dog has begun carrying messages between rooms because Jack and Jill are not speaking.'),
('emotional-safety-vulnerability',1,'Jill comes home after a discouraging day and says she doesn''t want a solution. Jack has already opened a search page labeled ''Five ways to fix this immediately.'''),
('emotional-safety-vulnerability',2,'At a crowded celebration, Jack slips outside and admits he isn''t feeling as strong as everyone thinks. Jill is the only one who noticed he left.'),
('emotional-safety-vulnerability',3,'A small disagreement about a bill turns unexpectedly heated. Beneath Jack''s frustration is a fear he has not yet found the words to explain.'),
('emotional-safety-vulnerability',4,'Jill starts to ask a personal question then withdraws it. Jack has to decide what to do with the awkward space that opens between them.'),
('emotional-safety-vulnerability',5,'After a long quiet drive, Jack says there is something behind his silence. Jill turns down the radio, but the exit for their house is coming up fast.'),
('emotional-safety-vulnerability',6,'Jill begins crying while folding a perfectly ordinary towel. Jack is holding a basket of laundry and has absolutely no idea what the tears mean.'),
('emotional-safety-vulnerability',7,'Jack has rehearsed a difficult truth several times in the bathroom mirror. Jill hears him say, ''Can we sit down for a minute?'''),
('emotional-safety-vulnerability',8,'A passing remark at a party makes Jill unexpectedly unsure of herself. Jack notices she has stopped joining the conversation and offers an easy joke that may miss the point.'),
('emotional-safety-vulnerability',9,'Jack has been asking whether Jill still values him, but every question comes out as a challenge. Tonight he tries again at the kitchen counter.'),
('emotional-safety-vulnerability',10,'Jill politely declines a request, and Jack''s smile disappears. Neither wants a ''no'' to turn into another obligation to explain.'),
('romance-courtship',1,'At 9:18 p.m., the children are finally asleep. Jack lights two candles; Jill discovers a mountain of forgotten laundry balanced on the dining table.'),
('romance-courtship',2,'Jill has dressed up for a simple evening out. Jack greets her while checking the weather and looking for his keys, unaware of how much thought went into the moment.'),
('romance-courtship',3,'While dinner burns slightly, Jack starts dancing in the kitchen. Jill has flour on her sleeve and a timer counting down from thirty seconds.'),
('romance-courtship',4,'Jack and Jill have canceled three date nights in a row. A restaurant text announces that tonight''s reservation is in forty minutes and neither is dressed.'),
('romance-courtship',5,'Jack realizes the anniversary is today when a delivery person arrives carrying flowers addressed to the neighbors. Jill is watching him through the window.'),
('romance-courtship',6,'Jill makes an unmistakably playful invitation while Jack is sorting receipts. The receipt printer beeps just as she asks whether he has five minutes.'),
('romance-courtship',7,'An old ticket stub falls out of a book. Jack remembers the concert; Jill remembers how he held her hand in the parking lot afterward.'),
('romance-courtship',8,'Both spouses agree to put away their phones for dinner. Five minutes in, two mysterious notification sounds come from the next room.'),
('romance-courtship',9,'Jack suggests repeating their first date. Jill gently says she would rather invent a memory they have never had before, and the babysitter arrives in fifteen minutes.'),
('romance-courtship',10,'A promising weekend trip is almost canceled after a hectic workweek. Their overnight bag sits by the door beside a growing list of unfinished chores.'),
('desire-physical-intimacy',1,'Over morning coffee, Jill tries to raise a delicate question about closeness. Jack assumes the topic is a complaint and glances at the clock; they have ten quiet minutes.'),
('desire-physical-intimacy',2,'Jack reaches out to suggest a romantic evening. Jill is exhausted and unsure how to say she would love closeness without feeling obligated to follow a particular script.'),
('desire-physical-intimacy',3,'The couple''s routines have changed after a demanding season. Jack opens a conversation about what affection looks like now, but neither has a simple answer.'),
('desire-physical-intimacy',4,'Jill notices that their spontaneous hugs have nearly disappeared. Jack sits at the other end of the sofa holding a blanket that used to cover both of them.'),
('desire-physical-intimacy',5,'Jack has been trying to find words for a personal preference and a boundary. Jill has invited an honest conversation, but the silence stretches before he begins.'),
('desire-physical-intimacy',6,'After an affectionate gesture is declined, Jill worries she is unwanted. Jack wants to reassure her without pretending that his own limits don''t matter.'),
('desire-physical-intimacy',7,'Jack says a kind but clear no to a romantic invitation. Jill must choose how to respond to the disappointment without turning affection into a debt.'),
('desire-physical-intimacy',8,'A reassuring hand on the shoulder lands badly after a tense day. Jill steps back; Jack realizes they may have understood the same touch differently.'),
('desire-physical-intimacy',9,'Over a weekend breakfast, Jack and Jill discover that they each use the word ''close'' to mean something different. Their competing plans for the afternoon are still on the fridge.'),
('desire-physical-intimacy',10,'Jill reaches for Jack''s hand as they settle onto the couch. He hesitates, and the couple have a chance to explore readiness without pressure or resentment.'),
('trust-commitment',1,'Jack asks to borrow Jill''s phone to find a photograph. A password prompt appears, and a simple request becomes an uncomfortable conversation about privacy and openness.'),
('trust-commitment',2,'At a family gathering, Jill hears a relative refer to a private story Jack shared in confidence. Dinner is about to begin, and neither knows how to address it.'),
('trust-commitment',3,'A friendly coworker sends Jack a late-night message. Jill sees the notification flash on the kitchen table and wonders what boundaries they have actually agreed on.'),
('trust-commitment',4,'Jill discovers that Jack left out one important detail when explaining a decision. The original news was ordinary; the missing detail is now the bigger story.'),
('trust-commitment',5,'Jack receives an enticing opportunity that could alter their shared plans. He drafts an enthusiastic response, then realizes he hasn''t mentioned the offer to Jill.'),
('trust-commitment',6,'The weekend plan changes unexpectedly while Jill is away. Jack updates the calendar but forgets that one promise depended on the original plan.'),
('trust-commitment',7,'Jack discovers the small task he promised to complete is still unfinished. Jill has already rearranged tomorrow because she expected it to be done.'),
('trust-commitment',8,'An old commitment collides with a sudden request from a friend. Jill wants to be helpful, but Jack has cleared his own afternoon around their promise.'),
('trust-commitment',9,'An old screenshot resurfaces in a group chat, stripped of its context. Jack and Jill have to decide what belongs online and what belongs only between them.'),
('trust-commitment',10,'Jill has accepted Jack''s apology but still checks whether a promise has been kept. Jack is tempted to demand that the matter finally be closed.'),
('partnership-family',1,'A blended-family holiday calendar covers the refrigerator door. Three different children have three different ideas about where Christmas should happen, and everyone is asking the adults for an answer.'),
('partnership-family',2,'Jill receives an unexpected career invitation just as childcare arrangements fall through. Jack is staring at a schedule that suddenly has no available adult.'),
('partnership-family',3,'Both Jack and Jill accept separate Tuesday evening commitments. The calendar reveals that the same child needs a ride to two different places at once.'),
('partnership-family',4,'Jack notices the appointment reminder twenty minutes too late. Jill has already rearranged work once and does not want to become the household reminder system.'),
('partnership-family',5,'The grandparents have each booked a visit for the same weekend. An enthusiastic family group chat is filling with plans that Jack and Jill never approved.'),
('partnership-family',6,'Jill unfolds the family task list she has quietly kept in her head all week. Jack reads it and realizes half of the tasks never appeared on their shared calendar.'),
('partnership-family',7,'Sunday evening arrives with unwashed uniforms, a broken printer and two people certain they did more than their fair share. A fresh weekly plan sits unopened.'),
('partnership-family',8,'Jack and Jill discover they gave a child opposite answers about a new rule. The child is already preparing a persuasive slideshow for the more generous parent.'),
('partnership-family',9,'An aging parent''s care appointment is moved forward. Jack and Jill each want to help but are staring at the same limited hours in their week.'),
('partnership-family',10,'The school calls: a child needs picking up immediately. Jack and Jill are both in meetings, and each assumed the other was the emergency contact.'),
('money-stewardship',1,'An unexpected bonus lands in the account. Jack starts researching a weekend trip; Jill opens the spreadsheet labeled ''Emergency Fund.'' Both are smiling for very different reasons.'),
('money-stewardship',2,'Jack wants to save for a long-delayed dream; Jill wants to pay down a burden. A single paycheck has become the centerpiece of two perfectly reasonable plans.'),
('money-stewardship',3,'The couple''s first budget conversation in months begins with colored pens and optimism. Fifteen minutes later, the pens are arranged in a defensive line.'),
('money-stewardship',4,'A credit-card bill arrives earlier than expected. Jack takes a deep breath; Jill has a question about a balance neither has discussed recently.'),
('money-stewardship',5,'Jill walks through the door carrying a four-hundred-dollar purchase. Jack has just checked the balance and is deciding whether surprise means excitement or alarm.'),
('money-stewardship',6,'Jack has chosen a generous gift for someone they love. Jill notices the price and remembers the household expense they promised to handle first.'),
('money-stewardship',7,'Jill announces a purchase she thought was practical. Jack remembers a different spending limit, but neither is sure when the limit became an agreement.'),
('money-stewardship',8,'Jack discovers that Jill has been building a private emergency fund. The conversation may involve legitimate independence, trust and safety rather than a simple accusation.'),
('money-stewardship',9,'Jack loves saving every spare dollar; Jill values occasional shared treats. They find themselves arguing over a modest Saturday outing rather than their actual financial goals.'),
('money-stewardship',10,'While sorting old receipts, Jack and Jill realize they have never agreed what ''enough'' means. Their long-term goals look very different on two sticky notes.'),
('faith-purpose',1,'Jill agrees to help with one more community event. Jack supports the cause but looks at the three evenings already missing from the family calendar.'),
('faith-purpose',2,'Sunday morning begins with different expectations. Jack has his shoes on for church; Jill needs a slower morning and has not decided whether she wants to attend.'),
('faith-purpose',3,'A relative advises Jack and Jill to ''forgive and forget'' a difficult breach of trust. Neither believes those two actions are necessarily the same thing.'),
('faith-purpose',4,'An unexpected vocation opportunity calls for a major move. Jack is excited; Jill is thinking about roots, commitments and the future they both imagined.'),
('faith-purpose',5,'Jack is asked to lead another church project. He wants to say yes, but Jill has quietly carried the household workload during his last commitment.'),
('faith-purpose',6,'Jack and Jill each write down what they hope their life will stand for. The lists overlap in surprising places and diverge in others.'),
('faith-purpose',7,'At bedtime, Jill suggests sharing a moment of prayer or reflection. Jack is uncomfortable with the expectation and wants an invitation that leaves room to choose.'),
('faith-purpose',8,'A dinner-table question about belief sparks a more difficult conversation than either expected. The dessert is cooling while both try to explain what matters.'),
('faith-purpose',9,'Jack admits he is uncertain about something he once believed firmly. Jill wants to be supportive without supplying an answer he didn''t ask for.'),
('faith-purpose',10,'Their child repeats something Jack said about generosity while Jill recalls an entirely different example from the week. Both wonder what their everyday choices teach.'),
('adventure-play',1,'Jack unfolds a trail map dotted with mountain peaks. Jill holds the brochure for a lakeside reading retreat. They have one weekend and a single reservation.'),
('adventure-play',2,'A hand-painted backroad sign promises ''World''s Largest Something.'' Jack turns the wheel toward it; Jill checks the arrival time for the carefully planned dinner.'),
('adventure-play',3,'At a couples'' game night, Jack keeps a running score on a napkin. Jill discovers the next challenge requires teamwork and no one knows how to win.'),
('adventure-play',4,'Jack and Jill have accidentally enrolled in a beginner pottery class instead of the cooking workshop they expected. The instructor hands them each a suspicious lump of clay.'),
('adventure-play',5,'A friend offers two tickets to a surprise outing. Jack lights up; Jill is tired of being asked to be spontaneous without knowing what she''s agreeing to.'),
('adventure-play',6,'A jar labeled ''Something New'' contains folded suggestions from both spouses. The first slip pulled out is so strange they suspect a practical joke.'),
('adventure-play',7,'Jack and Jill say yes to a small local festival neither has visited. The event map reveals an activity that is much more adventurous than the advertisement suggested.'),
('adventure-play',8,'They pass a turnoff they''ve ignored for years. The road sign has faded and Jack wonders aloud whether this is the afternoon to stop following the usual route.'),
('adventure-play',9,'After months of dropping coins into a jar, their shared adventure budget is finally ready. Jack has one destination in mind, Jill another, and the jar comes with no instructions.'),
('adventure-play',10,'Two tickets arrive for an unfamiliar live experience. Jack is thrilled, Jill is nervous, and the venue''s welcome email includes the phrase ''audience participation.'''),
('individuality-growth',1,'Jill notices Jack has started describing himself differently than he did a year ago. He wants to explain the change but isn''t sure how it will be received.'),
('individuality-growth',2,'Jack and Jill disagree about a choice their friends take for granted. The restaurant conversation stalls when each realizes the other won''t simply change their mind.'),
('individuality-growth',3,'Jill uncovers an old sketchbook containing the business idea she never pursued. Jack is making plans for the weekend, unaware of the opportunity she''s considering.'),
('individuality-growth',4,'As they clear a child''s old bedroom, Jack begins imagining a future Jill hasn''t pictured. A half-packed box sits between their two maps of the next chapter.'),
('individuality-growth',5,'A blank five-year planner arrives as a gift. Jack and Jill fill the first page differently and realize that uncertainty may be part of growing together.'),
('individuality-growth',6,'Jack snaps over a minor delay and immediately recognizes the reaction as his. Jill asks what happens next, and he has a choice about owning it.'),
('individuality-growth',7,'Jill receives a chance to pursue a new career. The email is exciting and unsettling because their shared routines have depended on her current role.'),
('individuality-growth',8,'At a reunion, old friends describe Jack as he used to be. Jill hears the story and wonders how to honor the person he has become instead.'),
('individuality-growth',9,'Jack feels ready for a major change; Jill is content with the current season. The difference becomes visible as they plan an ordinary Saturday.'),
('individuality-growth',10,'Jill asks for an evening of personal space after a draining week. Jack wants connection and is unsure how to honor her request without withdrawing.')
),
existing as (
 select id,slug,title,petal_slug,learning_objective,primary_lenses,
 row_number() over(partition by petal_slug order by title,slug) as rank
 from public.deep_dive_stories
),
prepared as (
 select e.*,case when e.rank%2=1 then 'shared' else 'individual' end as mode,
 ceil(e.rank/2.0)::int as slot,scene_inputs.opening_scene
 from existing e join scene_inputs using(petal_slug,rank)
)
insert into public.anthos_jj2_scenarios(source_story_id,petal_slug,mode,slot,title,opening_scene,learning_objective,research_lenses,status)
select id,petal_slug,mode,slot,title,opening_scene,coalesce(learning_objective,'Explore the relationship dilemma'),coalesce(primary_lenses,'{}'::text[]),'draft'
from prepared
on conflict(source_story_id) do nothing;